(()=>{const totalTL=Number(prompt("Total TL:","55000")),agrisRate=Number(prompt("TL/hr dengan Agris:","19000")),agrisCostPerHour=Number(prompt("Agris yang digunakan per jam:","32000")),normalRate=Number(prompt("TL/hr tanpa Agris:","11000")),currentAgris=Number(prompt("Agris yang digunakan:","32000"));if(!totalTL||!agrisRate||!agrisCostPerHour||!normalRate||totalTL<0||agrisRate<=0||agrisCostPerHour<=0||normalRate<=0){alert("Invalid input.");return;}const maxAgrisHours=currentAgris/agrisCostPerHour,maxAgrisTL=maxAgrisHours*agrisRate;let agrisTL=0,normalTL=0,hoursWithAgris=0,hoursWithoutAgris=0;if(totalTL<=maxAgrisTL){agrisTL=totalTL;hoursWithAgris=agrisTL/agrisRate;}else{agrisTL=maxAgrisTL;normalTL=totalTL-maxAgrisTL;hoursWithAgris=maxAgrisHours;hoursWithoutAgris=normalTL/normalRate;}const formatHours=h=>{const totalSecs=Math.floor(h*3600),hrs=Math.floor(totalSecs/3600),mins=Math.floor((totalSecs%3600)/60),secs=totalSecs%60;return`${hrs} Hours ${mins} Minutes ${secs} Seconds`;},totalSeconds=Math.floor((hoursWithAgris+hoursWithoutAgris)*3600),hours=Math.floor(totalSeconds/3600),minutes=Math.floor((totalSeconds%3600)/60),seconds=totalSeconds%60,result=`Total Time: ${hours} Hours ${minutes} Minutes ${seconds} Seconds\n`+`Time with Agris: ${formatHours(hoursWithAgris)}\n`+`Time without Agris: ${formatHours(hoursWithoutAgris)}`;alert(result);console.log(result);})();
